package com.petlis.service.impl;
import org.junit.jupiter.api.Test;import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petlis.common.exception.BusinessException;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LegacyBankPaymentDispatchTest {
 @Test void disabledGatewayNeverClaimsRequestOrConnects(){var execution=mock(LegacyBankPaymentExecutionService.class);var gateway=new LegacyBankGatewayClient();var dispatch=new LegacyBankPaymentDispatchService(execution,gateway);assertFalse(dispatch.capabilities().get("bankPaymentSend"));assertThrows(BusinessException.class,()->dispatch.execute("req",false));verify(execution,never()).claim(anyString(),anyString(),anyBoolean());}
 @Test void networkRunsAfterClaimAndUnknownResultIsPersistedWithoutRetry(){var execution=mock(LegacyBankPaymentExecutionService.class);var gateway=mock(LegacyBankGatewayClient.class);when(gateway.available()).thenReturn(true);when(gateway.merchant()).thenReturn("LOCALTEST");when(execution.allowed(anyString())).thenReturn(true);var claim=new LegacyBankPaymentExecutionService.Claimed("ORDER1","token",Map.of("merOrdrNo","ORDER1"));when(execution.claim("req","LOCALTEST",false)).thenReturn(claim);when(gateway.exchange(any(),anyMap())).thenThrow(new LegacyBankGatewayClient.UnknownResult());new LegacyBankPaymentDispatchService(execution,gateway).execute("req",false);var ordered=inOrder(execution,gateway);ordered.verify(execution).claim("req","LOCALTEST",false);ordered.verify(gateway).exchange(LegacyBankProtocol.Method.PREPAY,claim.parameters());ordered.verify(execution).unknown("req","token");verify(gateway,times(1)).exchange(any(),anyMap());}
 @Test void outerTransactionIsRejectedBeforeClaimOrNetwork(){var execution=mock(LegacyBankPaymentExecutionService.class);var gateway=mock(LegacyBankGatewayClient.class);TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThrows(BusinessException.class,()->new LegacyBankPaymentDispatchService(execution,gateway).execute("req",false));verifyNoInteractions(execution,gateway);}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}}
 @Test void queryRoutesVerifiedResponseToOriginalSettlement()throws Exception{var execution=mock(LegacyBankPaymentExecutionService.class);var gateway=mock(LegacyBankGatewayClient.class);when(gateway.available()).thenReturn(true);when(gateway.merchant()).thenReturn("LOCALTEST");when(execution.allowed("queryEnabled")).thenReturn(true);var claim=new LegacyBankPaymentExecutionService.Claimed("ORDER1","token",Map.of("oriMerOrdrNo","ORDER1"));when(execution.claim("req","LOCALTEST",true)).thenReturn(claim);var response=new ObjectMapper().readTree("{\"retCode\":\"00000\"}");when(gateway.exchange(LegacyBankProtocol.Method.PAY_QUERY,claim.parameters())).thenReturn(response);new LegacyBankPaymentDispatchService(execution,gateway).execute("req",true);verify(execution).finish("req","token",true,response);}
 @Test void legacyLogFormattingKeepsPhpDivisionAndSprintfAtLargeValues(){assertEquals("12.50",LegacyBankPaymentExecutionService.legacyLogAmount("1250").toPlainString());assertEquals("100000000000000.00",LegacyBankPaymentExecutionService.legacyLogAmount("9999999999999999").toPlainString());}
}
